SELECT count(*) FROM deals_enriched WHERE deal_date BETWEEN DATE '2024-01-01' AND DATE '2024-12-31' AND product_base IN ('сахар белый','сахар-песок');
SELECT round(sum(amount_uzs)), count(*) FROM deals_enriched WHERE deal_date BETWEEN DATE '2024-01-01' AND DATE '2024-12-31' AND product_base IN ('сахар белый','сахар-песок') AND status<>'Аннулирован(Не оплачен)';
SELECT product_base AS g, NULL AS k, NULL AS u, count(*) FROM deals_enriched d  WHERE deal_date BETWEEN DATE '2024-01-01' AND DATE '2024-12-31' AND product_base IN ('сахар белый','сахар-песок') GROUP BY 1, 2, 3 ORDER BY 4 DESC NULLS LAST LIMIT 8

